CREATE TABLE "usuarios" ("id" TEXT NOT NULL PRIMARY KEY, "nome" TEXT NOT NULL, "email" TEXT NOT NULL, "senhaHash" TEXT, "criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "usuarios_email_key" ON "usuarios"("email");
CREATE TABLE "categorias" ("id" TEXT NOT NULL PRIMARY KEY, "nome" TEXT NOT NULL, "tipo" TEXT NOT NULL);
CREATE UNIQUE INDEX "categorias_nome_key" ON "categorias"("nome");
CREATE TABLE "transacoes" ("id" TEXT NOT NULL PRIMARY KEY, "tipo" TEXT NOT NULL, "valor" DECIMAL(18,2) NOT NULL, "descricao" TEXT NOT NULL, "data" TIMESTAMP(3) NOT NULL, "prioridade" TEXT NOT NULL, "criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "usuarioId" TEXT NOT NULL, "categoriaId" TEXT NOT NULL, CONSTRAINT "transacoes_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "usuarios"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "transacoes_categoriaId_fkey" FOREIGN KEY ("categoriaId") REFERENCES "categorias"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "transacoes_usuarioId_data_idx" ON "transacoes"("usuarioId", "data");
CREATE INDEX "transacoes_usuarioId_tipo_data_idx" ON "transacoes"("usuarioId", "tipo", "data");
CREATE INDEX "transacoes_usuarioId_categoriaId_data_idx" ON "transacoes"("usuarioId", "categoriaId", "data");
CREATE TABLE "sessoes" ("id" TEXT NOT NULL PRIMARY KEY, "tokenHash" TEXT NOT NULL, "csrfToken" TEXT NOT NULL, "expiraEm" TIMESTAMP(3) NOT NULL, "criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "usuarioId" TEXT NOT NULL, CONSTRAINT "sessoes_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "usuarios"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "sessoes_tokenHash_key" ON "sessoes"("tokenHash");
CREATE INDEX "sessoes_usuarioId_idx" ON "sessoes"("usuarioId");
CREATE INDEX "sessoes_expiraEm_idx" ON "sessoes"("expiraEm");
